layout='<LinearLayout xmlns:android="http://schemas.android.com/apk/res/android" android:layout_width="match_parent" android:layout_height="match_parent" android:background="#010C1F" android:orientation="vertical"><ScrollView android:layout_width="match_parent" android:layout_height="match_parent"><LinearLayout android:layout_width="match_parent" android:layout_height="wrap_content" android:orientation="vertical" android:padding="12dp"><TextView android:layout_width="match_parent" android:layout_height="wrap_content" android:text="OTG Flasher Pro v1.8 REAL" android:textColor="#00D4FF" android:textSize="18sp" android:textStyle="bold" android:gravity="center"/><TextView android:id="@+id/tvUsb" android:layout_width="match_parent" android:layout_height="wrap_content" android:text="USB: Checking..." android:textColor="#FFAA00"/><Button android:id="@+id/btnAdb" android:layout_width="match_parent" android:layout_height="48dp" android:text="ADB DEVICES" android:background="@drawable/bg_btn_cyan"/><Button android:id="@+id/btnFastboot" android:layout_width="match_parent" android:layout_height="48dp" android:text="FASTBOOT" android:background="@drawable/bg_btn_orange"/><TextView android:id="@+id/tvPath" android:layout_width="match_parent" android:layout_height="wrap_content" android:text="No file" android:textColor="#888"/><Button android:id="@+id/btnPick" android:layout_width="match_parent" android:layout_height="44dp" android:text="PICK IMG"/><Button android:id="@+id/btnFlashBoot" android:layout_width="match_parent" android:layout_height="48dp" android:text="FLASH BOOT" android:background="@drawable/bg_btn_cyan"/><Button android:id="@+id/btnFlashRecovery" android:layout_width="match_parent" android:layout_height="48dp" android:text="FLASH RECOVERY" android:background="@drawable/bg_btn_cyan"/><Button android:id="@+id/btnFlashSystem" android:layout_width="match_parent" android:layout_height="48dp" android:text="FLASH SYSTEM" android:background="@drawable/bg_btn_cyan"/><Button android:id="@+id/btnFlashVbmeta" android:layout_width="match_parent" android:layout_height="48dp" android:text="VBMETA DISABLE" android:background="@drawable/bg_btn_orange"/><Button android:id="@+id/btnUnlock" android:layout_width="match_parent" android:layout_height="48dp" android:text="UNLOCK BL" android:background="@drawable/bg_btn_orange"/><Button android:id="@+id/btnWipe" android:layout_width="match_parent" android:layout_height="48dp" android:text="WIPE DATA" android:background="@drawable/bg_btn_orange"/><Button android:id="@+id/btnReboot" android:layout_width="match_parent" android:layout_height="48dp" android:text="REBOOT" android:background="@drawable/bg_btn_orange"/><TextView android:id="@+id/tvLog" android:layout_width="match_parent" android:layout_height="350dp" android:background="#000000" android:text="> Ready" android:textColor="#00FF88"/></LinearLayout></ScrollView></LinearLayout>'
open("app/src/main/res/layout/activity_main.xml","w").write('<?xml version="1.0" encoding="utf-8"?>'+layout)
java='package com.otgflasher.pro;\nimport android.app.PendingIntent; import android.content.*; import android.hardware.usb.*; import android.net.Uri; import android.os.Bundle; import android.widget.*; import androidx.appcompat.app.AppCompatActivity; import java.io.*; import java.util.HashMap;\npublic class MainActivity extends AppCompatActivity {\nTextView tvLog, tvUsb, tvPath; String selectedPath=""; String adbPath=""; UsbManager usbManager; static final String ACTION_USB="com.otgflasher.pro.USB_PERMISSION";\n@Override protected void onCreate(Bundle b){ super.onCreate(b); setContentView(R.layout.activity_main); tvLog=findViewById(R.id.tvLog); tvUsb=findViewById(R.id.tvUsb); tvPath=findViewById(R.id.tvPath); usbManager=(UsbManager)getSystemService(Context.USB_SERVICE); adbPath=getApplicationInfo().nativeLibraryDir+"/libadb.so"; log("> ADB: "+adbPath); checkUsb(); findViewById(R.id.btnPick).setOnClickListener(v->pickFile()); findViewById(R.id.btnAdb).setOnClickListener(v->execReal("adb devices")); findViewById(R.id.btnFastboot).setOnClickListener(v->execReal("fastboot devices")); findViewById(R.id.btnFlashBoot).setOnClickListener(v->flash("boot")); findViewById(R.id.btnFlashRecovery).setOnClickListener(v->flash("recovery")); findViewById(R.id.btnFlashSystem).setOnClickListener(v->flash("system")); findViewById(R.id.btnFlashVbmeta).setOnClickListener(v->execReal("fastboot flash vbmeta --disable-verity --disable-verification "+(selectedPath.isEmpty()?"vbmeta.img":selectedPath))); findViewById(R.id.btnUnlock).setOnClickListener(v->execReal("fastboot flashing unlock")); findViewById(R.id.btnWipe).setOnClickListener(v->execReal("fastboot -w")); findViewById(R.id.btnReboot).setOnClickListener(v->execReal("fastboot reboot")); registerReceiver(usbReceiver,new IntentFilter(ACTION_USB)); }\nvoid checkUsb(){ HashMap<String,UsbDevice> list=usbManager.getDeviceList(); if(list.isEmpty()){tvUsb.setText("USB: No OTG");} else {for(UsbDevice d:list.values()){tvUsb.setText("USB Found"); requestPerm(d);} } }\nvoid requestPerm(UsbDevice dev){ PendingIntent pi=PendingIntent.getBroadcast(this,0,new Intent(ACTION_USB),PendingIntent.FLAG_MUTABLE); usbManager.requestPermission(dev,pi); }\nBroadcastReceiver usbReceiver=new BroadcastReceiver(){ public void onReceive(Context c,Intent i){ if(ACTION_USB.equals(i.getAction())){ if(i.getBooleanExtra(UsbManager.EXTRA_PERMISSION_GRANTED,false)){tvUsb.setText("USB OK");} } } };\nvoid pickFile(){ Intent intent=new Intent(Intent.ACTION_GET_CONTENT); intent.setType("*/*"); startActivityForResult(intent,99); }\n@Override protected void onActivityResult(int req,int res,Intent data){ super.onActivityResult(req,res,data); if(req==99 && res==RESULT_OK && data!=null){ Uri uri=data.getData(); try{ InputStream is=getContentResolver().openInputStream(uri); File out=new File(getCacheDir(),"temp.img"); FileOutputStream fos=new FileOutputStream(out); byte[] buf=new byte[8192]; int len; while((len=is.read(buf))>0) fos.write(buf,0,len); fos.close(); is.close(); selectedPath=out.getAbsolutePath(); tvPath.setText(selectedPath); } catch(Exception e){} } }\nvoid flash(String part){ if(selectedPath.isEmpty()) return; execReal("fastboot flash "+part+" "+selectedPath); }\nvoid execReal(String cmd){ log("> $ "+cmd); new Thread(()->{ try{ File f=new File(adbPath); Process p; String fullCmd=cmd.startsWith("adb")?adbPath+" "+cmd.substring(3):adbPath+" "+cmd; if(f.exists() && f.length()>1000) p=Runtime.getRuntime().exec(fullCmd); else { try{ p=Runtime.getRuntime().exec(new String[]{"su","-c",cmd}); } catch(Exception e){ p=Runtime.getRuntime().exec(new String[]{"sh","-c",cmd}); } } BufferedReader br=new BufferedReader(new InputStreamReader(p.getInputStream())); String line; while((line=br.readLine())!=null){ String l=line; runOnUiThread(()->log(l)); } p.waitFor(); } catch(Exception e){} }).start(); }\nvoid log(String s){ runOnUiThread(()->{ tvLog.append("\\n"+s); }); }\n}'
open("app/src/main/java/com/otgflasher/pro/MainActivity.java","w").write(java)
